package in.lmt.property;
import in.lmt.shared.*;
import in.lmt.identity.ChallengeService;
import in.lmt.workspace.WorkspaceCommands;
import in.lmt.commercial.*;
import java.util.*;
import java.time.Instant;
import java.math.BigDecimal;
import java.sql.*;
import java.util.function.Supplier;
import org.springframework.jdbc.core.simple.JdbcClient;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import tools.jackson.databind.ObjectMapper;
@Service @Transactional
public class Properties {
 private final JdbcClient db;private final WorkspaceCommands scope;private final Entitlements entitlements;private final RentableCapacity capacity;private final Audit audit;private final ObjectMapper json;
 public Properties(JdbcClient db,WorkspaceCommands scope,Entitlements entitlements,RentableCapacity capacity,Audit audit,ObjectMapper json){this.db=db;this.scope=scope;this.entitlements=entitlements;this.capacity=capacity;this.audit=audit;this.json=json;}
 public record Property(UUID id,UUID workspaceId,String code,String name,String addressLine,String locality,String city,String state,String pin,String latitude,String longitude,String houseRules,String status,String ownershipStatus,int version,String etag,Instant updatedAt){}
 public record Space(UUID id,UUID propertyId,UUID parentId,String kind,String code,String name,String category,String area,String areaUnit,int capacity,int bathrooms,int balconies,String furnishing,String rentalMode,String rent,String deposit,String maintenance,String currency,String status,int version,String etag){}
 public record Page<T>(List<T> items,String nextCursor,long totalMatching,Instant asOf){}
 public record History(UUID id,UUID resourceId,String action,int version,String summary,Instant occurredAt){}
 public record Detail(Property property,List<String> readinessBlockers,List<String> archiveBlockers,List<History> history,String sharedCountingMode){}
 private String tag(String kind,UUID id,int v){return "\""+kind+"-"+id+"-v"+v+"\"";}
 private static String decimal(ResultSet r,String key)throws SQLException{BigDecimal n=r.getBigDecimal(key);return n==null?null:n.toPlainString();}
 private Property property(ResultSet r)throws SQLException{UUID id=r.getObject("id",UUID.class);int v=r.getInt("version");return new Property(id,r.getObject("workspace_id",UUID.class),r.getString("code"),r.getString("name"),r.getString("address_line"),r.getString("locality"),r.getString("city"),r.getString("state"),r.getString("pin"),decimal(r,"latitude"),decimal(r,"longitude"),r.getString("house_rules"),r.getString("status"),r.getString("ownership_status"),v,tag("property",id,v),r.getTimestamp("updated_at").toInstant());}
 private Space space(ResultSet r)throws SQLException{UUID id=r.getObject("id",UUID.class);int v=r.getInt("version");return new Space(id,r.getObject("property_id",UUID.class),r.getObject("parent_id",UUID.class),r.getString("kind"),r.getString("code"),r.getString("name"),r.getString("category"),decimal(r,"area"),r.getString("area_unit"),r.getInt("capacity"),r.getInt("bathrooms"),r.getInt("balconies"),r.getString("furnishing"),r.getString("rental_mode"),decimal(r,"rent"),decimal(r,"deposit"),decimal(r,"maintenance"),"INR",r.getString("status"),v,tag("space",id,v));}
 private Property find(UUID w,UUID id){return db.sql("SELECT * FROM property_record WHERE workspace_id=:w AND id=:id").param("w",w).param("id",id).query((r,n)->property(r)).optional().orElseThrow(()->new ApiProblem(404,"PROPERTY_NOT_FOUND","Property is unavailable."));}
 private Space findSpace(UUID w,UUID p,UUID id){return db.sql("SELECT * FROM property_space WHERE workspace_id=:w AND property_id=:p AND id=:id").param("w",w).param("p",p).param("id",id).query((r,n)->space(r)).optional().orElseThrow(()->new ApiProblem(404,"SPACE_NOT_FOUND","Space is unavailable in this property."));}
 @Transactional(readOnly=true)
 public Space getSpace(UUID actor,UUID w,UUID p,UUID id){scope.requireOwner(w,actor);find(w,p);return findSpace(w,p,id);}
 private void match(String expected,String actual){if(expected==null||expected.isBlank())throw new ApiProblem(428,"PRECONDITION_REQUIRED","Refresh and review the current version.");if(!expected.equals(actual))throw new ApiProblem(412,"VERSION_STALE","The record changed. Refresh and review before confirming.");}
 private void reason(String value){if(value.strip().length()<10)throw new ApiProblem(422,"REASON_REQUIRED","Provide a reason of at least 10 non-padding characters.","reason");}
 private void writable(Property p){if(p.status().equals("archived"))throw new ApiProblem(409,"PROPERTY_ARCHIVED","Restore the property before changing its setup.");}
 private void history(UUID actor,UUID w,UUID p,UUID resource,String action,int version,String summary){db.sql("INSERT INTO property_history(id,workspace_id,property_id,resource_id,actor_id,action,version,summary) VALUES(:id,:w,:p,:r,:a,:action,:v,:s)").param("id",UUID.randomUUID()).param("w",w).param("p",p).param("r",resource).param("a",actor).param("action",action).param("v",version).param("s",summary).update();audit.record(actor,w,action,resource);}
 private <T>T command(UUID actor,UUID w,String op,UUID key,Object body,Class<T> type,Supplier<T> work){
  scope.requireOwner(w,actor);db.sql("SELECT pg_advisory_xact_lock(hashtextextended(:key,0))").param("key","membership:"+w).query().singleRow();db.sql("SELECT pg_advisory_xact_lock(hashtextextended(:key,0))").param("key","property-workspace:"+w).query().singleRow();scope.requireOwner(w,actor);
  String hash=ChallengeService.hash(json.writeValueAsString(body));var prior=db.sql("SELECT request_hash,result::text FROM property_command WHERE actor_id=:a AND workspace_id=:w AND operation=:o AND request_key=:k").param("a",actor).param("w",w).param("o",op).param("k",key).query().listOfRows();
  if(!prior.isEmpty()){if(!hash.equals(prior.getFirst().get("request_hash")))throw new ApiProblem(409,"IDEMPOTENCY_CONFLICT","This key belongs to a different property confirmation.");return json.readValue((String)prior.getFirst().get("result"),type);}
  T result=work.get();db.sql("INSERT INTO property_command(actor_id,workspace_id,operation,request_key,request_hash,result) VALUES(:a,:w,:o,:k,:h,CAST(:r AS jsonb))").param("a",actor).param("w",w).param("o",op).param("k",key).param("h",hash).param("r",json.writeValueAsString(result)).update();return result;
 }
 private UUID after(String cursor,String context){if(cursor==null)return new UUID(0,0);try{var parts=new String(Base64.getUrlDecoder().decode(cursor),java.nio.charset.StandardCharsets.UTF_8).split("/");if(parts.length!=2||!parts[0].equals(context))throw new IllegalArgumentException();return UUID.fromString(parts[1]);}catch(RuntimeException e){throw new ApiProblem(422,"INVALID_CURSOR","Refresh this property list.","cursor");}}
 private <T>Page<T> page(List<T> rows,long count,String context,java.util.function.Function<T,UUID> id){boolean more=rows.size()>25;List<T> items=more?rows.subList(0,25):rows;String next=more?Base64.getUrlEncoder().withoutPadding().encodeToString((context+"/"+id.apply(items.getLast())).getBytes(java.nio.charset.StandardCharsets.UTF_8)):null;return new Page<>(items,next,count,Instant.now());}
 @Transactional(readOnly=true,isolation=org.springframework.transaction.annotation.Isolation.REPEATABLE_READ)
 public Page<Property> list(UUID actor,UUID w,String cursor,String status){scope.requireOwner(w,actor);if(!Set.of("all","current","archived").contains(status))throw new ApiProblem(422,"INVALID_FILTER","Choose all, current or archived properties.","status");String context=actor+":"+w+":"+status;String where="workspace_id=:w AND (:status='all' OR (:status='current' AND status<>'archived') OR (:status='archived' AND status='archived'))";var rows=db.sql("SELECT * FROM property_record WHERE "+where+" AND id>:after ORDER BY id LIMIT 26").param("w",w).param("status",status).param("after",after(cursor,context)).query((r,n)->property(r)).list();long total=db.sql("SELECT count(*) FROM property_record WHERE "+where).param("w",w).param("status",status).query(Long.class).single();return page(rows,total,context,Property::id);}
 @Transactional(readOnly=true,isolation=org.springframework.transaction.annotation.Isolation.REPEATABLE_READ)
 public Page<Space> spaces(UUID actor,UUID w,UUID p,String cursor){scope.requireOwner(w,actor);find(w,p);String context=actor+":"+w+":"+p;var rows=db.sql("SELECT * FROM property_space WHERE workspace_id=:w AND property_id=:p AND id>:after ORDER BY id LIMIT 26").param("w",w).param("p",p).param("after",after(cursor,context)).query((r,n)->space(r)).list();long total=db.sql("SELECT count(*) FROM property_space WHERE workspace_id=:w AND property_id=:p").param("w",w).param("p",p).query(Long.class).single();return page(rows,total,context,Space::id);}
 @Transactional(readOnly=true,isolation=org.springframework.transaction.annotation.Isolation.REPEATABLE_READ)
 public Detail detail(UUID actor,UUID w,UUID p){scope.requireOwner(w,actor);var current=find(w,p);var blockers=new ArrayList<String>();if(current.addressLine().isBlank()||current.city().isBlank()||current.state().isBlank()||current.pin().isBlank())blockers.add("Complete the Indian property address and PIN code.");if(!current.ownershipStatus().equals("verified"))blockers.add("Ownership and operational authority require verified evidence. No verification has been recorded.");if(db.sql("SELECT count(*) FROM property_space WHERE property_id=:p AND kind IN ('unit','bed') AND status='ready'").param("p",p).query(Long.class).single()==0)blockers.add("Add and review at least one rentable item.");blockers.add("Activation awaits configured operating/signing policies, payee verification and occupancy/finance integration; draft setup does not grant these authorities.");
  var archive=new ArrayList<String>();if(db.sql("SELECT count(*) FROM property_space WHERE property_id=:p AND status<>'archived'").param("p",p).query(Long.class).single()>0)archive.add("Archive all child spaces first. Archiving a property never cascades through inventory.");var history=db.sql("SELECT * FROM property_history WHERE property_id=:p ORDER BY occurred_at DESC,id DESC LIMIT 50").param("p",p).query((r,n)->new History(r.getObject("id",UUID.class),r.getObject("resource_id",UUID.class),r.getString("action"),r.getInt("version"),r.getString("summary"),r.getTimestamp("occurred_at").toInstant())).list();return new Detail(current,blockers,archive,history,capacity.sharedMode(w));}
 private void validate(PropertyController.Input b){if((b.latitude()==null)!=(b.longitude()==null))throw new ApiProblem(422,"INVALID_COORDINATES","Provide both map coordinates, or leave both blank.","latitude");if(b.latitude()!=null&&(new BigDecimal(b.latitude()).abs().compareTo(new BigDecimal("90"))>0||new BigDecimal(b.longitude()).abs().compareTo(new BigDecimal("180"))>0))throw new ApiProblem(422,"INVALID_COORDINATES","Latitude must be within ±90 and longitude within ±180.","latitude");}
 private BigDecimal number(String s){return s==null?null:new BigDecimal(s);}
 private void saveProperty(UUID w,UUID id,PropertyController.Input b){validate(b);if(db.sql("SELECT EXISTS(SELECT 1 FROM property_record WHERE workspace_id=:w AND lower(code)=lower(:code) AND id<>:id)").param("w",w).param("code",b.code()).param("id",id).query(Boolean.class).single())throw new ApiProblem(409,"DUPLICATE_PROPERTY_CODE","Property identifier already exists in this workspace.");db.sql("UPDATE property_record SET code=:code,name=:name,address_line=:address,locality=:locality,city=:city,state=:state,pin=:pin,latitude=:lat,longitude=:lon,house_rules=:rules,updated_at=clock_timestamp() WHERE id=:id AND workspace_id=:w").param("code",b.code()).param("name",b.name().strip()).param("address",b.addressLine().strip()).param("locality",b.locality().strip()).param("city",b.city().strip()).param("state",b.state().strip()).param("pin",b.pin()).param("lat",number(b.latitude()),Types.NUMERIC).param("lon",number(b.longitude()),Types.NUMERIC).param("rules",b.houseRules()).param("id",id).param("w",w).update();}
 public Property create(UUID actor,UUID w,UUID key,PropertyController.Input b){return command(actor,w,"property.create",key,b,Property.class,()->{entitlements.require(w,"PROPERTY_CREATE");validate(b);if(db.sql("SELECT EXISTS(SELECT 1 FROM property_record WHERE workspace_id=:w AND lower(code)=lower(:code))").param("w",w).param("code",b.code()).query(Boolean.class).single())throw new ApiProblem(409,"DUPLICATE_PROPERTY_CODE","Property identifier already exists.");UUID id=UUID.randomUUID();db.sql("INSERT INTO property_record(id,workspace_id,code,name,address_line,locality,city,state,pin) VALUES(:id,:w,:code,:name,'','','','','')").param("id",id).param("w",w).param("code",b.code()).param("name",b.name().strip()).update();saveProperty(w,id,b);history(actor,w,id,id,"property.created",1,"Property draft created; ownership remains unverified.");return find(w,id);});}
 public Property edit(UUID actor,UUID w,UUID id,UUID key,String expected,PropertyController.Input b){return command(actor,w,"property.edit:"+id,key,Arrays.asList(expected,b),Property.class,()->{entitlements.require(w,"PROPERTY_EDIT");var current=find(w,id);match(expected,current.etag());writable(current);saveProperty(w,id,b);db.sql("UPDATE property_record SET version=version+1 WHERE id=:id").param("id",id).update();var result=find(w,id);history(actor,w,id,id,"property.edited",result.version(),"Property address/configuration updated; no tenancy terms changed.");return result;});}
 public Property archive(UUID actor,UUID w,UUID id,UUID key,String expected,String reason){return command(actor,w,"property.archive:"+id,key,Arrays.asList(expected,reason),Property.class,()->{reason(reason);entitlements.require(w,"PROPERTY_ARCHIVE");var d=detail(actor,w,id);match(expected,d.property().etag());if(!d.archiveBlockers().isEmpty())throw new ApiProblem(409,"ARCHIVE_BLOCKED",String.join(" ",d.archiveBlockers()));if(d.property().status().equals("archived"))throw new ApiProblem(409,"ALREADY_ARCHIVED","Property is already archived.");db.sql("UPDATE property_record SET status='archived',version=version+1,updated_at=clock_timestamp() WHERE id=:id").param("id",id).update();var result=find(w,id);history(actor,w,id,id,"property.archived",result.version(),reason);return result;});}
 public Property restore(UUID actor,UUID w,UUID id,UUID key,String expected,String reason){return command(actor,w,"property.restore:"+id,key,Arrays.asList(expected,reason),Property.class,()->{reason(reason);entitlements.require(w,"PROPERTY_CREATE");var current=find(w,id);match(expected,current.etag());if(!current.status().equals("archived"))throw new ApiProblem(409,"NOT_ARCHIVED","Property is not archived.");db.sql("UPDATE property_record SET status='draft',version=version+1,updated_at=clock_timestamp() WHERE id=:id").param("id",id).update();var result=find(w,id);history(actor,w,id,id,"property.restored",result.version(),reason);return result;});}
 public Detail review(UUID actor,UUID w,UUID id,UUID key,String expected,String reason){return command(actor,w,"property.review:"+id,key,Arrays.asList(expected,reason),Detail.class,()->{reason(reason);entitlements.require(w,"PROPERTY_EDIT");var current=find(w,id);match(expected,current.etag());writable(current);db.sql("UPDATE property_record SET status='review_required',version=version+1,updated_at=clock_timestamp() WHERE id=:id").param("id",id).update();history(actor,w,id,id,"property.readiness_reviewed",current.version()+1,reason);return detail(actor,w,id);});}
 private void validateSpace(UUID w,UUID p,UUID id,PropertyController.SpaceInput b){
  if(b.area()!=null&&number(b.area()).signum()<=0)throw new ApiProblem(422,"INVALID_AREA","Area must be positive.","area");
  if((b.kind().equals("bed")||b.rentalMode().equals("shared"))&&!capacity.sharedAvailable(w))throw new ApiProblem(409,"COUNTING_POLICY_REQUIRED","Shared inventory is unavailable under this workspace counting policy. Existing bindings are preserved; live shared counting requires approved configuration.");
  if(b.kind().equals("unit")&&b.rentalMode().equals("shared")&&db.sql("SELECT count(*) FROM property_space WHERE parent_id=:id AND status<>'archived'").param("id",id).query(Long.class).single()>b.capacity())throw new ApiProblem(409,"BED_CAPACITY_EXCEEDED","Physical capacity cannot be reduced below the number of active beds.");
  if(!b.kind().equals("unit")&&b.rentalMode().equals("shared"))throw new ApiProblem(422,"INVALID_RENTAL_MODE","Only units can be shared containers.","rentalMode");
  if(b.kind().equals("building")&&b.parentId()!=null)throw new ApiProblem(422,"INVALID_PARENT","Buildings belong directly to the property.","parentId");
  if(b.kind().equals("floor")&&b.parentId()==null||b.kind().equals("bed")&&b.parentId()==null)throw new ApiProblem(422,"PARENT_REQUIRED","Choose the enclosing building or shared unit.","parentId");
  if(b.parentId()!=null){Space parent=findSpace(w,p,b.parentId());if(parent.status().equals("archived"))throw new ApiProblem(409,"PARENT_ARCHIVED","Restore the parent before changing child spaces.");boolean allowed=switch(b.kind()){case "floor"->parent.kind().equals("building");case "unit"->Set.of("building","floor").contains(parent.kind());case "bed"->parent.kind().equals("unit")&&parent.rentalMode().equals("shared");default->false;};if(!allowed)throw new ApiProblem(422,"INVALID_PARENT","The parent type does not match this hierarchy level.","parentId");if(b.kind().equals("bed")&&db.sql("SELECT count(*) FROM property_space WHERE parent_id=:parent AND status<>'archived' AND id<>:id").param("parent",b.parentId()).param("id",id).query(Long.class).single()>=parent.capacity())throw new ApiProblem(409,"BED_CAPACITY_EXCEEDED","The shared unit has no remaining physical bed capacity.");}
  if(db.sql("SELECT EXISTS(SELECT 1 FROM property_space WHERE property_id=:p AND lower(code)=lower(:code) AND id<>:id)").param("p",p).param("code",b.code()).param("id",id).query(Boolean.class).single())throw new ApiProblem(409,"DUPLICATE_SPACE_CODE","Space identifier already exists in this property.");
  if(b.kind().equals("unit")&&b.rentalMode().equals("shared")&&db.sql("SELECT count(*) FROM property_space WHERE parent_id=:id AND status<>'archived'").param("id",id).query(Long.class).single()>b.capacity())throw new ApiProblem(409,"BED_CAPACITY_EXCEEDED","Capacity cannot be reduced below the current bed count.");
 }
 private void saveSpace(UUID id,PropertyController.SpaceInput b){db.sql("UPDATE property_space SET parent_id=:parent,code=:code,name=:name,category=:category,area=:area,area_unit=:areaUnit,capacity=:capacity,bathrooms=:bathrooms,balconies=:balconies,furnishing=:furnishing,rent=:rent,deposit=:deposit,maintenance=:maintenance,updated_at=clock_timestamp() WHERE id=:id")
 .param("parent",b.parentId(),Types.OTHER).param("code",b.code()).param("name",b.name().strip()).param("category",b.category().strip()).param("area",number(b.area()),Types.NUMERIC).param("areaUnit",b.areaUnit()).param("capacity",b.capacity()).param("bathrooms",b.bathrooms()).param("balconies",b.balconies()).param("furnishing",b.furnishing()).param("rent",number(b.rent()),Types.NUMERIC).param("deposit",number(b.deposit()),Types.NUMERIC).param("maintenance",number(b.maintenance()),Types.NUMERIC).param("id",id).update();}
 public Space addSpace(UUID actor,UUID w,UUID p,UUID key,PropertyController.SpaceInput b){return command(actor,w,"space.create:"+p,key,b,Space.class,()->{entitlements.require(w,"RENTABLE_CREATE");writable(find(w,p));UUID id=UUID.randomUUID();validateSpace(w,p,id,b);db.sql("INSERT INTO property_space(id,workspace_id,property_id,kind,code,name,rental_mode) VALUES(:id,:w,:p,:kind,:code,:name,:mode)").param("id",id).param("w",w).param("p",p).param("kind",b.kind()).param("code",b.code()).param("name",b.name()).param("mode",b.rentalMode()).update();saveSpace(id,b);if(capacity.counted(w,b.kind(),b.rentalMode()))capacity.consume(w,id);history(actor,w,p,id,"space.created",1,"Created "+b.kind()+" "+b.code()+"; no occupancy, listing or agreement created.");return findSpace(w,p,id);});}
 public Space editSpace(UUID actor,UUID w,UUID p,UUID id,UUID key,String expected,PropertyController.SpaceInput b){return command(actor,w,"space.edit:"+id,key,Arrays.asList(expected,b),Space.class,()->{entitlements.require(w,"PROPERTY_EDIT");writable(find(w,p));var current=findSpace(w,p,id);match(expected,current.etag());if(current.status().equals("archived"))throw new ApiProblem(409,"SPACE_ARCHIVED","Restore the space before editing.");if(!current.kind().equals(b.kind())||!current.rentalMode().equals(b.rentalMode()))throw new ApiProblem(409,"CLASSIFICATION_IMMUTABLE","Create a separately reviewed space to change physical kind or rental counting mode.");validateSpace(w,p,id,b);saveSpace(id,b);db.sql("UPDATE property_space SET version=version+1,status=CASE WHEN status='ready' THEN 'draft' ELSE status END WHERE id=:id").param("id",id).update();var result=findSpace(w,p,id);history(actor,w,p,id,"space.edited",result.version(),"Configuration changed; prior readiness is reset for review. Existing contractual terms are not changed.");return result;});}
 public Space state(UUID actor,UUID w,UUID p,UUID id,UUID key,String expected,PropertyController.State b){return command(actor,w,"space.state:"+id,key,Arrays.asList(expected,b),Space.class,()->{reason(b.reason());entitlements.require(w,"PROPERTY_EDIT");writable(find(w,p));var current=findSpace(w,p,id);match(expected,current.etag());if(current.status().equals(b.status()))throw new ApiProblem(409,"STATE_UNCHANGED","Space already has this state.");if(current.parentId()!=null&&findSpace(w,p,current.parentId()).status().equals("archived"))throw new ApiProblem(409,"PARENT_ARCHIVED","Restore the parent first.");if(b.status().equals("ready")&&(current.kind().equals("unit")||current.kind().equals("bed"))&&(current.rent()==null||current.deposit()==null||current.maintenance()==null||current.category().isBlank()))throw new ApiProblem(409,"READINESS_INCOMPLETE","Record a category and explicit rent, deposit and maintenance values before marking physical setup ready. Zero is permitted when intentional.");
  if(b.status().equals("archived")&&db.sql("SELECT count(*) FROM property_space WHERE parent_id=:id AND status<>'archived'").param("id",id).query(Long.class).single()>0)throw new ApiProblem(409,"ARCHIVE_BLOCKED","Archive child spaces first.");
  if(current.status().equals("archived")){entitlements.require(w,"RENTABLE_CREATE");if((current.kind().equals("bed")||current.rentalMode().equals("shared"))&&!capacity.sharedAvailable(w))throw new ApiProblem(409,"COUNTING_POLICY_REQUIRED","Shared inventory is unavailable under this workspace counting policy.");if(current.kind().equals("bed")){var parent=findSpace(w,p,current.parentId());if(db.sql("SELECT count(*) FROM property_space WHERE parent_id=:id AND status<>'archived'").param("id",parent.id()).query(Long.class).single()>=parent.capacity())throw new ApiProblem(409,"BED_CAPACITY_EXCEEDED","The shared unit has no remaining physical capacity.");}if(capacity.counted(w,current.kind(),current.rentalMode()))capacity.consume(w,id);}else if(b.status().equals("archived")&&capacity.counted(w,current.kind(),current.rentalMode()))capacity.release(w,id);
  db.sql("UPDATE property_space SET status=:status,version=version+1,updated_at=clock_timestamp() WHERE id=:id").param("status",b.status()).param("id",id).update();var result=findSpace(w,p,id);history(actor,w,p,id,"space.state_changed",result.version(),b.reason());return result;});}
}
